import { Pinecone } from "@pinecone-database/pinecone";
import config from "config";

export class PineconeClient {
	private client: Pinecone;
	private INDEX_NAME = "wellness-buddy-index";
	private NAMESPACES = [
		"mental wellness",
		"career success",
		"sleep",
		"safety",
		"nutrition",
	];

	constructor() {
		const apiKey = config.get<string>("PINECONE_API_KEY");
		if (!apiKey) {
			throw new Error("PINECONE_API_KEY is not set in config");
		}
		this.client = new Pinecone({ apiKey });
	}

	async createIndex() {
		const existing = await this.client.listIndexes();
		if (existing.indexes?.some((i) => i.name === this.INDEX_NAME)) {
			return;
		}

		await this.client.createIndex({
			name: this.INDEX_NAME,
			dimension: 3072,
			metric: "cosine",
			spec: {
				serverless: {
					cloud: "aws",
					region: "us-east-1",
				},
			},
		});
	}

	async upsert(
		records: {
			id: string;
			values: number[];
			metadata: Record<string, any>;
		}[],
		namespace: string = ""
	) {
		const index = this.client.index(this.INDEX_NAME).namespace(namespace);
		await index.upsert(records);
	}
	async deleteAll() {
		const index = this.client.index(this.INDEX_NAME);
		await index.deleteAll();
	}

	/**
	 * Query the index for top K similar vectors to the given embedding
	 * @param vector The query vector
	 * @param namespace Optional namespace
	 * @param topK Number of results to return
	 * @returns Array of matches with id, score, and metadata
	 */
	async query(
		vector: number[],
		namespaces: string[] = this.NAMESPACES,
		topK: number = 5
	) {
		const allResults: {
			id: string;
			score?: number;
			metadata?: Record<string, any>;
			namespace: string;
		}[] = [];

		for (const ns of namespaces) {
			const index = this.client.index(this.INDEX_NAME).namespace(ns);
			const result = await index.query({
				vector,
				topK,
				includeMetadata: true,
			});

			const matches =
				result.matches?.map((m) => ({
					id: m.id,
					score: m.score,
					metadata: m.metadata,
					namespace: ns,
				})) || [];

			allResults.push(...matches);
		}

		allResults.sort((a, b) => (b.score ?? 0) - (a.score ?? 0));
		return allResults.slice(0, topK);
	}
}

const pineconeClient = new PineconeClient();
export default pineconeClient;
